	display: inline-block;
	font-weight:normal;
	font-size:14px;
}
.dropselect select {
	border: 1px solid #C5C5C5 !important;  /*Remove border*/
    -webkit-appearance: none;  /*Remove estilo padrÃ£o do chrome e safari */
