    text-overflow: "";  /* Remove seta padrÃ£o do firefox */
    color: #4D4D4D;
	padding: 1px;
}

select::-ms-expand { /* Remove estilizaÃ§Ã£o do IE 10+ */
    display: none;
}/* FIM Menu dropdown select */
